package com.spawnershop.gui;
import com.spawnershop.SpawnerShopPlugin; import com.spawnershop.api.SpawnerShopOpenEvent; import com.spawnershop.config.*; import com.spawnershop.service.TransactionService; import com.spawnershop.util.Text; import net.kyori.adventure.text.Component; import org.bukkit.*; import org.bukkit.entity.Player; import org.bukkit.inventory.*; import org.bukkit.inventory.meta.ItemMeta;
public final class ShopView { private final SpawnerShopPlugin plugin; private final ShopRepository repo; private final TransactionService transactions; public ShopView(SpawnerShopPlugin p,ShopRepository r,TransactionService t){plugin=p;repo=r;transactions=t;} public void open(Player p){int size=plugin.getConfig().getInt("shop.size",54);if(size<9||size>54||size%9!=0)size=54;Inventory inv=Bukkit.createInventory(new ShopHolder(),size,Component.text(Text.color(plugin.getConfig().getString("shop.title","&6Spawner Shop"))));String bg=plugin.getConfig().getString("shop.background.material","BLACK_STAINED_GLASS_PANE");Material bm=Material.matchMaterial(bg);if(bm!=null){ItemStack item=new ItemStack(bm);ItemMeta meta=item.getItemMeta();meta.displayName(Component.text(Text.color(plugin.getConfig().getString("shop.background.name"," "))));item.setItemMeta(meta);for(int i=0;i<size;i++)inv.setItem(i,item);}for(ShopItem item:repo.all())if(item.slot()<size)inv.setItem(item.slot(),transactions.stack(item,1));
int buySlot=plugin.getConfig().getInt("shop.buy-all.slot",46);int sellSlot=plugin.getConfig().getInt("shop.sell-all.slot",47);if(buySlot>=0&&buySlot<size)inv.setItem(buySlot,button(plugin.getConfig().getString("shop.buy-all.material","EMERALD"),plugin.getConfig().getString("shop.buy-all.name","&a&lBUY ALL SPAWNERS")));if(sellSlot>=0&&sellSlot<size)inv.setItem(sellSlot,button(plugin.getConfig().getString("shop.sell-all.material","GOLD_INGOT"),plugin.getConfig().getString("shop.sell-all.name","&6&lSELL ALL SPAWNERS")));p.openInventory(inv); Bukkit.getPluginManager().callEvent(new SpawnerShopOpenEvent(p));}
private ItemStack button(String material,String name){Material type=Material.matchMaterial(material);ItemStack item=new ItemStack(type==null?Material.BARRIER:type);ItemMeta meta=item.getItemMeta();meta.displayName(Component.text(Text.color(name)));item.setItemMeta(meta);return item;}
}
